package kr.tong.sky;
import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.time.*;import java.util.*;import java.io.*;import java.net.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class)
@Config(manifest=Config.NONE,sdk=35,packageName="kr.tong.sky")
public class CollectionRecoveryTest {
 static class Backend implements SharedCache.Backend {
  JSONObject body,stale;int staleReads,reads,writes;String sha="0";
  Backend()throws Exception{body=new JSONObject().put("schema",1).put("origin","ICN").put("region","아시아나").put("records",new JSONObject());}
  public SharedCache.Document read()throws Exception{reads++;return new SharedCache.Document(sha,new JSONObject((staleReads-->0?stale:body).toString()));}
  public void write(JSONObject b,String expected)throws Exception{if(!sha.equals(expected))throw new SharedCache.Conflict();stale=new JSONObject(body.toString());body=new JSONObject(b.toString());sha=""+(++writes);}
 }
 SharedCache client(Backend b){return new SharedCache(b,"ICN","아시아나","ours","OZ");}
 @Test public void claimThenStaleReadRecoversBeforeLocalReuse()throws Exception{Backend b=new Backend();SharedCache c=client(b);try(var d=c.claim(new JSONArray(),System.currentTimeMillis(),true)){assertFalse(d.busy());}b.staleReads=1;assertEquals(0,c.reuseLocalRegion(k->null,List.of(),System.currentTimeMillis()));assertEquals(1,b.writes);assertEquals(3,b.reads);assertEquals("ours",b.body.getJSONObject("lease").getString("owner"));}
 @Test public void checkpointRetriesStaleReadAndCanReleaseItsOwnLease()throws Exception{Backend b=new Backend();SharedCache c=client(b);try(var d=c.claim(new JSONArray(),System.currentTimeMillis(),true)){}b.staleReads=2;c.checkpointPending(Map.of(),true,System.currentTimeMillis());assertFalse(b.body.has("lease"));assertEquals(2,b.writes);}
 @Test public void foreignAndMissingLeaseNeverGetReclaimedOrWritten()throws Exception{for(boolean other:List.of(false,true)){Backend b=new Backend();if(other)b.body.put("lease",new JSONObject().put("owner","another-device").put("until",System.currentTimeMillis()+900000));String before=b.body.toString();try{client(b).checkpoint(Map.of(),true,System.currentTimeMillis());fail("must stop");}catch(IOException expected){assertTrue(expected.getMessage().contains("다시 확인"));}assertEquals(before,b.body.toString());assertEquals(0,b.writes);assertEquals(3,b.reads);}}
 @Test public void sharedReadsUseFreshKeysButImmutableBlobsDoNot()throws Exception{List<URL> urls=new ArrayList<>();GitHubStore g=new GitHubStore("ICN","asiana","",u->{urls.add(u);return new HttpURLConnection(u){public void connect(){}public void disconnect(){}public boolean usingProxy(){return false;}};},ms->{});String path="/contents/test.json?ref=tong-sky-data";HttpURLConnection first=g.connection(path,"GET"),second=g.connection(path,"GET");assertNotEquals(urls.get(0),urls.get(1));assertTrue(urls.get(0).getQuery().contains("tong_read="));assertEquals("no-cache",first.getRequestProperty("Cache-Control"));g.connection("/git/blobs/abc","GET");assertNull(urls.get(2).getQuery());g.connection(path,"PUT");assertFalse(urls.get(3).getQuery().contains("tong_read"));}
 @Test public void koreanBookingDayOpensAtNineKoreanTime()throws Exception{ZonedDateTime before=ZonedDateTime.of(2026,11,6,8,59,59,0,Search.KST),at=before.plusSeconds(1);assertEquals(LocalDate.of(2027,10,31),Search.lastDate(false,before));assertEquals(LocalDate.of(2027,11,1),Search.lastDate(false,at));assertEquals(Search.lastDate(false,before),Search.lastDate(false,before.withZoneSameInstant(ZoneId.of("UTC"))));assertEquals(LocalDate.of(2027,10,31),Search.lastDate(true,at));}
 @Test public void wholeRegionPlanningUsesOpeningTime()throws Exception{JSONObject cat=new JSONObject().put("regions",new JSONObject().put("유럽",new JSONArray().put(new JSONObject().put("code","LHR"))));for(int hour:new int[]{8,9}){ZonedDateTime now=ZonedDateTime.of(2026,11,6,hour,0,0,0,Search.KST);JSONArray q=RegionBatch.create("ICN","유럽",cat,now.toLocalDate(),now.toInstant().toEpochMilli()).getJSONArray("queries");assertEquals(hour==8?"2027-10":"2027-11",q.getJSONObject(q.length()-1).getString("month"));}}
 @Test public void migrationAnnotationOnlyAppliesAfterPublishedTransferDate(){assertFalse(AsianaQueryFailure.transferPeriod("2027-07",LocalDate.of(2026,11,4)));assertTrue(AsianaQueryFailure.transferPeriod("2027-07",LocalDate.of(2026,11,5)));assertTrue(AsianaQueryFailure.transferPeriod("2027-09",LocalDate.of(2026,11,4)));assertFalse(AsianaQueryFailure.transferPeriod("2027-06",LocalDate.of(2026,11,6)));assertFalse(AsianaQueryFailure.transferPeriod("invalid",LocalDate.of(2026,11,6)));}
}
